import React from 'react';
import { graphql, withPrefix } from 'gatsby';
import Helmet from 'react-helmet';
import Layout from '../components/Layout';
import Post from '../components/Post';
import { useSiteMetadata } from '../hooks';

const PostTemplate = ({ data }) => {
  const { title: siteTitle, subtitle: siteSubtitle, author, url } = useSiteMetadata();
  const { frontmatter } = data.markdownRemark;
  const { title: postTitle, description: postDescription, socialImage, date } = frontmatter;
  const metaDescription = postDescription !== null ? postDescription : siteSubtitle;
  const canonicalPath = data.markdownRemark.fields.slug;
  const metaImagePath = socialImage != null ? socialImage : author.photo;
  const metaImageUrl = url + withPrefix(metaImagePath);
  const articleLdJson = {
    '@context': 'https://schema.org',
    '@type': 'BlogPosting',
    headline: postTitle,
    datePublished: date,
    dateModified: date,
    author: { '@type': 'Person', name: author?.name },
    publisher: {
      '@type': 'Organization',
      name: author?.name,
      logo: { '@type': 'ImageObject', url: url + withPrefix(author?.photo || '') }
    },
    image: metaImageUrl,
    description: metaDescription,
    url: url + withPrefix(canonicalPath)
  };

  return (
    <Layout
      title={`${postTitle} - ${siteTitle}`}
      description={metaDescription}
      socialImage={socialImage}
      canonicalPath={canonicalPath}
      ogType="article"
    >
      <Helmet>
        <script type="application/ld+json">{JSON.stringify(articleLdJson)}</script>
      </Helmet>
      <Post post={data.markdownRemark} />
    </Layout>
  );
};

export const query = graphql`
  query PostBySlug($slug: String!) {
    markdownRemark(fields: { slug: { eq: $slug } }) {
      id
      html
      fields {
        slug
        tagSlugs
      }
      frontmatter {
        date
        description
        tags
        title
        socialImage
      }
    }
  }
`;

export default PostTemplate;
