import React from 'react';
import { withPrefix } from 'gatsby';
import { useSiteMetadata } from '../../../hooks';
import styles from './Newsletter.module.scss';

const Newsletter = () => {
  const { url } = useSiteMetadata();
  const feedPath = withPrefix('/rss.xml');
  const feedUrl = `${url || ''}${feedPath}`;
  const emailLink = `https://blogtrottr.com/?btr_url=${encodeURIComponent(feedUrl)}`;

  return (
    <div className={styles['newsletter']}>
      <h3 className={styles['newsletter__title']}>Subscribe to the newsletter</h3>
      <p className={styles['newsletter__text']}>
        Get new posts by email via Blogtrottr (free), or subscribe via RSS.
      </p>
      <div className={styles['newsletter__actions']}>
        <a
          className={styles['newsletter__button']}
          href={emailLink}
          target="_blank"
          rel="noopener noreferrer"
        >
          Email me new posts
        </a>
        <a
          className={styles['newsletter__link']}
          href={feedPath}
          target="_blank"
          rel="noopener noreferrer"
        >
          RSS
        </a>
      </div>
    </div>
  );
};

export default Newsletter;